import Foundation

/// Decoding support for rejecting unsupported keyed values.
public enum MetaCodableStrictDecodingRegistry {
    private static let lock = NSLock()
    nonisolated(unsafe) private static var keysByType:
        [ObjectIdentifier: Set<String>] = [:]

    /// Registers keys generated by a MetaCodable class.
    public static func register(type: Any.Type, keys: [String]) {
        lock.lock()
        defer { lock.unlock() }
        let identifier = ObjectIdentifier(type)
        keysByType[identifier, default: []].formUnion(keys)
    }

    /// Returns keys registered for a type.
    static func keys(for type: Any.Type) -> Set<String> {
        lock.lock()
        defer { lock.unlock() }
        return keysByType[ObjectIdentifier(type)] ?? []
    }
}

public extension Decoder {
    /// Throws when the keyed value contains keys outside the provided set.
    ///
    /// - Parameters:
    ///   - allowedKeys: The string values recognized by the generated decoder
    ///   at this container level.
    ///   - type: The type being decoded, used in the error context.
    /// - Throws: ``DecodingError/dataCorrupted(_:)`` when unsupported keys
    /// are present or when the container cannot be inspected.
    func rejectUnknownKeys(
        allowedKeys: [String],
        type: Any.Type
    ) throws {
        let rawContainer = try container(
            keyedBy: DynamicCodableIdentifier<String>.self
        )
        let allowedKeys = Set(allowedKeys).union(
            MetaCodableStrictDecodingRegistry.keys(for: type)
        )
        let unknownKeys = rawContainer.allKeys
            .map(\.stringValue)
            .filter { !allowedKeys.contains($0) }
            .sorted()
        guard !unknownKeys.isEmpty else { return }

        let context = DecodingError.Context(
            codingPath: codingPath,
            debugDescription:
                "Unsupported keys found while decoding \(type): "
                + unknownKeys.joined(separator: ", ")
        )
        throw DecodingError.dataCorrupted(context)
    }
}
